DELETE FROM public.checkins WHERE registration_id IN (SELECT r.id FROM public.registrations r JOIN public.participants p ON p.id=r.participant_id WHERE p.email ILIKE 'helpdesk.luminus@gmail.com');
DELETE FROM public.registrations WHERE participant_id IN (SELECT id FROM public.participants WHERE email ILIKE 'helpdesk.luminus@gmail.com');
DELETE FROM public.participants WHERE email ILIKE 'helpdesk.luminus@gmail.com';